<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { couponReviewQueue, reviewCoupon, describeRules, reviewStatus, type CouponReviewRequest } from '../campus-coupon/api'
import PaginationBar from '../../campus-shared/PaginationBar.vue'
const rows = ref<CouponReviewRequest[]>([]), selected = ref<CouponReviewRequest | null>(null), status = ref('PENDING'), reason = ref(''), page = ref(1), total = ref(0), busy = ref(false), message = ref('')
async function load(next = 1) { busy.value = true; selected.value = null; reason.value = ''; try { const data = await couponReviewQueue(status.value, next); rows.value = data.items; page.value = data.page; total.value = data.total } catch (error) { message.value = error instanceof Error ? error.message : '审核列表加载失败' } finally { busy.value = false } }
onMounted(() => load())
async function decide(decision: string) { if (!selected.value) return; busy.value = true; message.value = ''; try { await reviewCoupon(selected.value.id, decision, reason.value.trim()); await load(page.value); message.value = '优惠审核决定已保存，商家可在通过后发布。' } catch (error) { message.value = error instanceof Error ? error.message : '审核失败' } finally { busy.value = false } }
</script>
<template><section><RouterLink class="text-link" to="/admin">← 返回管理端</RouterLink><h1>优惠内容审核</h1><label for="couponReviewStatus">优惠审核状态</label><select id="couponReviewStatus" v-model="status" :disabled="busy" @change="load()"><option value="PENDING">待审核</option><option value="APPROVED">审核通过</option><option value="REJECTED">审核驳回</option></select><p v-if="message" role="status">{{ message }}</p><div class="review-layout"><section><article v-for="row in rows" :key="row.id" class="review-record"><h2>{{ row.content.title }}</h2><p>门店编号 {{ row.content.merchantId }} · {{ reviewStatus[row.status] }}</p><button class="secondary" :disabled="busy" @click="selected = row; reason = ''">查看优惠申请</button></article><PaginationBar :page="page" :size="20" :total="total" :disabled="busy" @change="load" /></section><article v-if="selected"><h2>{{ selected.content.title }}</h2><p class="coupon-value">{{ describeRules(selected.content.couponType, selected.content.rules) }}</p><p>{{ selected.content.description }}</p><p>数量 {{ selected.content.totalStock }} 张</p><p>{{ new Date(selected.content.validFrom).toLocaleString() }} 至 {{ new Date(selected.content.validUntil).toLocaleString() }}</p><p>{{ selected.content.campusOnly ? '本校认证专享' : '普通活动' }}</p><section v-if="selected.status === 'PENDING'"><label for="offerReviewReason">优惠审核原因</label><textarea id="offerReviewReason" v-model="reason" maxlength="255" rows="3" /><div class="button-row"><button :disabled="busy || !reason.trim()" @click="decide('APPROVED')">通过优惠审核</button><button class="secondary" :disabled="busy || !reason.trim()" @click="decide('REJECTED')">驳回优惠审核</button></div></section></article></div></section></template>
